INSERT INTO verticalizzazioniparametribase (modulo, parametro, descrizione) VALUES ('AREA_RISERVATA','URL_LOGO','Url del logo da utilizzare nell''area riservata');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_GEPROT', 'CODICE_CC', 'Questo parametro rappresente il codice per conoscenza indicato nella tabella PROTOCOLLO_MODALITAINVIO, va quindi indicato lo stesso valore indicato nel campo CODICE della medesima tabella riguardante la modalità di invio PER CONOSCENZA. Se non valorizzato o se il valore non è corrispondente a quanto indicato nella tabella indicata, questo parametro sarà ignorato.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_GEPROT', 'INDIRIZZOTELEMATICO_GEN', 'Indirizzo Telematico Generico, questo parametro viene preso in considerazione solamente se il parametro INVIO_PEC è diverso da 1, ed è utile per non bloccare protocollazioni in partenza sprovvisti di Indirizzi Pec. Se il sistema non riesce a recuperare l''indirizzo pec dal domicilio elettronico (destiantari Richiedente, Azienda o Tecnico) o dall''anagrafica (qualsiasi altro destiantario) verrà recuperato il valore indicato in questo parametro, che è comunque un dato fittizio, questo consentirà di non bloccare la protocollazione in quanto l''indirizzo telematico del destinatario è un dato obbligatorio. Potrebbe comunque essere richiesto che venga restituito un errore, in tal caso non valorizzare questo parametro.');
